"""Generate fixed whole-utterance study audio; never called by the website.

Run build-number-bank.mts first, then this script with the pinned requirements.
--deps-target can reuse an existing pip --target install. Generated bytes receive
content-hashed filenames. An existing matching transcript/hash is not regenerated.
"""
import argparse
import asyncio
import hashlib
import json
from pathlib import Path
import sys

parser = argparse.ArgumentParser(description=__doc__)
parser.add_argument('--deps-target', type=Path)
parser.add_argument('--concurrency', type=int, default=4)
args = parser.parse_args()
if args.deps_target: sys.path.insert(0, str(args.deps_target.resolve()))
import edge_tts
from mutagen.mp3 import MP3

root = Path(__file__).resolve().parents[1]
bank_path = root/'src/lib/numbers/bank.json'
bank = json.loads(bank_path.read_text(encoding='utf-8'))
output = root/'public/number-audio/v1'
output.mkdir(parents=True, exist_ok=True)
voice = 'zh-CN-XiaoxiaoNeural'
bank['voice'] = 'Microsoft zh-CN-XiaoxiaoNeural, synthesized complete utterances'
semaphore = asyncio.Semaphore(max(1, min(args.concurrency, 6)))

def sha(raw): return hashlib.sha256(raw).hexdigest()

async def generate(item):
    script_hash = sha((item['hanzi'] + '。|' + voice + '|-10%').encode())
    old = root/('public'+item.get('audioSrc', ''))
    if old.is_file() and item.get('audioScriptSha256') == script_hash and sha(old.read_bytes()) == item.get('audioSha256'):
        return
    async with semaphore:
        temp = output/(item['id']+'.building.mp3')
        for attempt in range(3):
            try:
                await asyncio.wait_for(edge_tts.Communicate(item['hanzi']+'。', voice, rate='-10%').save(str(temp)), 45)
                duration = MP3(temp).info.length
                if duration < .3 or duration > 25: raise ValueError('Unexpected speech duration')
                raw = temp.read_bytes(); digest = sha(raw)
                target = output/(item['id']+'-'+digest[:12]+'.mp3')
                temp.replace(target)
                item.update(audioSrc='/number-audio/v1/'+target.name, audioSha256=digest,
                            audioScriptSha256=script_hash, durationSeconds=round(duration, 3))
                print('Generated '+item['id'], flush=True)
                return
            except Exception:
                if attempt == 2: raise
                await asyncio.sleep(2+attempt*2)

async def main():
    await asyncio.gather(*(generate(item) for item in bank['items']))
    bank['audioBuild'] = {'voice':voice, 'rate':'-10%', 'edgeTtsVersion':edge_tts.__version__,
                         'review':'All files checked for transcript pairing, checksum and decodable duration. Representative listening checks are recorded separately; no full human-review claim.'}
    bank_path.write_text(json.dumps(bank, ensure_ascii=False, indent=2)+'\n', encoding='utf-8', newline='\n')
    print('Completed '+str(len(bank['items']))+' fixed recordings.', flush=True)

asyncio.run(main())
